/*
 * A103579  Sophie Germain primes that are not Lucasian primes: primes p not 3
 *          (mod 4) such that 2p + 1 is prime.
 * https://oeis.org/A103579
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(n) = n‑th prime p such that p % 4 ≠ 3 and 2p+1 is also prime.
 *            The sequence is generated by a simple search using is_prime from
 *            <../utils/is_prime.h>
 * Range:     u8 n <= 9, u16 n <= 419, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   is_prime
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include "../utils/is_prime.h"

seq_t a(idx_t n) {
    /* The first term is 2. */
    if (n == 1)
        return (seq_t)2;

    idx_t count = 1;              /* we have already counted p = 2 */
    uint64_t p = 3;               /* start checking odd candidates from 3 */

    while (1) {
        /* p must be prime and not congruent to 3 modulo 4. */
        if (is_prime(p) && (p & 3ULL) == 1ULL) {
            uint64_t q = 2 * p + 1;      /* candidate 2p+1 */
            if (is_prime(q)) {
                ++count;
                if (count == n)
                    return (seq_t)p;
            }
        }
        p += 2;                 /* skip to the next odd number */
    }
}
